#!/usr/bin/env python
# coding: utf-8

"""
Plot oxygen-sweep results from saved CSV files.

This script does NOT rerun FBA. It reads the CSV files generated by
oxygen_sweep_063026_with_medium_intake.py and saves new plot images with a
larger objective-value y-axis range.

Expected input directory by default:
    <stm_model_test>/oxygen_sweep_results/063026

Expected CSV inputs:
    all_oxygen_sweep_df.csv
    all_medium_intake_df.csv     # optional, used for intake plots if present

Default plot output directory:
    <stm_model_test>/oxygen_sweep_results/063026/plots_from_csv
"""

from __future__ import annotations

import argparse
import os
from pathlib import Path

import matplotlib

# Use a non-interactive backend so plots can be saved on the cluster/headless jobs.
matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


# -----------------------------------------------------------------------------
# Paths
# -----------------------------------------------------------------------------

def find_stm_model_test_dir() -> Path:
    """Find the stm_model_test project directory on either local or cluster."""

    env_path = os.environ.get("STM_MODEL_TEST_DIR")
    if env_path:
        return Path(env_path).expanduser().resolve()

    cwd = Path.cwd().resolve()

    for path in [cwd, *cwd.parents]:
        if path.name == "stm_model_test":
            return path

    fallback_path = Path.home() / "2026_GEMs" / "stm_model_test"
    if fallback_path.exists():
        return fallback_path.resolve()

    raise FileNotFoundError(
        "Could not find the stm_model_test directory. Run this script from inside "
        "stm_model_test, or set STM_MODEL_TEST_DIR to the full path."
    )


def get_default_results_dir() -> Path:
    """Return the default directory containing oxygen-sweep CSV results."""

    env_path = os.environ.get("OXYGEN_SWEEP_RESULTS_DIR")
    if env_path:
        return Path(env_path).expanduser().resolve()

    project_dir = find_stm_model_test_dir()
    return project_dir / "oxygen_sweep_results" / "063026"


# -----------------------------------------------------------------------------
# Data loading and cleaning
# -----------------------------------------------------------------------------

def read_required_csv(path: Path) -> pd.DataFrame:
    """Read a required CSV file and raise a clear error if it is missing."""

    if not path.exists():
        raise FileNotFoundError(f"Missing required CSV file: {path}")

    return pd.read_csv(path)


def clean_oxygen_sweep_df(df: pd.DataFrame) -> pd.DataFrame:
    """Prepare oxygen-sweep results for plotting."""

    required_columns = {
        "model",
        "medium_condition",
        "oxygen",
        "status",
        "objective_value",
    }
    missing_columns = required_columns - set(df.columns)
    if missing_columns:
        raise ValueError(f"all_oxygen_sweep_df.csv is missing columns: {missing_columns}")

    df = df.copy()
    df["oxygen"] = pd.to_numeric(df["oxygen"], errors="coerce")
    df["objective_value"] = pd.to_numeric(df["objective_value"], errors="coerce")
    df = df.dropna(subset=["oxygen"])

    # Treat failed, infeasible, or missing objective values as zero growth for plotting.
    df["plot_objective_value"] = df["objective_value"].fillna(0)
    df["is_no_growth_or_failed"] = (
        df["objective_value"].isna()
        | np.isclose(df["plot_objective_value"], 0.0)
        | (df["status"] != "optimal")
    )

    return df


def clean_medium_intake_df(df: pd.DataFrame) -> pd.DataFrame:
    """Prepare medium-intake results for plotting."""

    df = df.copy()

    numeric_columns = [
        "oxygen",
        "objective_value",
        "medium_allowed_uptake",
        "exchange_flux",
        "intake_flux",
        "secretion_flux",
        "fraction_of_allowed_uptake",
    ]

    for column in numeric_columns:
        if column in df.columns:
            df[column] = pd.to_numeric(df[column], errors="coerce")

    return df


# -----------------------------------------------------------------------------
# Plot helpers
# -----------------------------------------------------------------------------

def safe_filename(text: str) -> str:
    """Convert a label into a safe filename component."""

    return (
        str(text)
        .replace(" ", "_")
        .replace("/", "_")
        .replace("\\", "_")
        .replace(":", "_")
        .replace(",", "")
        .lower()
    )


def get_ymax(plot_df: pd.DataFrame, requested_ymax: float | None) -> float:
    """Use the requested y-axis max unless the data exceed it."""

    observed_max = plot_df["plot_objective_value"].max(skipna=True)

    if pd.isna(observed_max):
        observed_max = 0.0

    if requested_ymax is None:
        return max(observed_max * 1.10, 1.0)

    return max(float(requested_ymax), observed_max * 1.10, 1.0)


def save_growth_plot(
    df: pd.DataFrame,
    filter_column: str,
    filter_value: str,
    group_column: str,
    title: str,
    filename: str,
    output_dir: Path,
    y_max: float | None = 20.0,
    xlim: tuple[float, float] = (0.0, 18.5),
) -> Path | None:
    """Save one oxygen-gradient growth plot."""

    plot_df = df[df[filter_column] == filter_value].copy()

    if plot_df.empty:
        print(f"Skipping empty plot: {title}")
        return None

    plot_df = plot_df.sort_values([group_column, "oxygen"])

    plt.figure(figsize=(9, 5.5))

    for group_name, group_df in plot_df.groupby(group_column, sort=True):
        group_df = group_df.sort_values("oxygen")

        plt.plot(
            group_df["oxygen"],
            group_df["plot_objective_value"],
            marker="o",
            linewidth=1,
            markersize=2,
            label=str(group_name),
        )

        no_growth_df = group_df[group_df["is_no_growth_or_failed"]]
        if not no_growth_df.empty:
            plt.scatter(
                no_growth_df["oxygen"],
                no_growth_df["plot_objective_value"],
                color="red",
                s=28,
                zorder=3,
                label=None,
            )

    plt.xlim(xlim)
    plt.ylim(0, get_ymax(plot_df, y_max))
    plt.xlabel("Oxygen uptake value for EX_o2_e")
    plt.ylabel("Objective value")
    plt.title(title)
    plt.grid(True)
    plt.legend(fontsize=8, bbox_to_anchor=(1.02, 1), loc="upper left", borderaxespad=0)

    save_path = output_dir / filename
    plt.savefig(save_path, dpi=150, bbox_inches="tight")
    plt.close()

    print(f"Saved growth plot: {save_path}")
    return save_path


def save_intake_line_plot(
    intake_df: pd.DataFrame,
    medium_condition: str,
    exchange_reaction: str,
    group_column: str,
    title: str,
    filename: str,
    output_dir: Path,
) -> Path | None:
    """Save one line plot for intake flux across the oxygen gradient."""

    required_columns = {
        "medium_condition",
        "exchange_reaction",
        "oxygen",
        "intake_flux",
        group_column,
    }
    missing_columns = required_columns - set(intake_df.columns)
    if missing_columns:
        print(f"Skipping intake plot because columns are missing: {missing_columns}")
        return None

    plot_df = intake_df[
        (intake_df["medium_condition"] == medium_condition)
        & (intake_df["exchange_reaction"] == exchange_reaction)
    ].copy()

    plot_df = plot_df.dropna(subset=["oxygen", "intake_flux"])

    if plot_df.empty:
        print(f"Skipping empty intake plot: {title}")
        return None

    plt.figure(figsize=(9, 5.5))

    for group_name, group_df in plot_df.groupby(group_column, sort=True):
        group_df = group_df.sort_values("oxygen")
        plt.plot(
            group_df["oxygen"],
            group_df["intake_flux"],
            marker="o",
            linewidth=1,
            markersize=2,
            label=str(group_name),
        )

    observed_max = plot_df["intake_flux"].max(skipna=True)
    y_upper = max(observed_max * 1.10, 1.0) if pd.notna(observed_max) else 1.0

    plt.xlim(0, 18.5)
    plt.ylim(0, y_upper)
    plt.xlabel("Oxygen uptake value for EX_o2_e")
    plt.ylabel("Intake flux")
    plt.title(title)
    plt.grid(True)
    plt.legend(fontsize=8, bbox_to_anchor=(1.02, 1), loc="upper left", borderaxespad=0)

    save_path = output_dir / filename
    plt.savefig(save_path, dpi=150, bbox_inches="tight")
    plt.close()

    print(f"Saved intake line plot: {save_path}")
    return save_path


def save_top_intake_bar_plot(
    intake_df: pd.DataFrame,
    model_name: str,
    medium_condition: str,
    output_dir: Path,
    oxygen_value: float | None = None,
    top_n: int = 15,
    include_oxygen: bool = False,
) -> Path | None:
    """Save a horizontal bar plot of top medium-metabolite intakes."""

    required_columns = {
        "model",
        "medium_condition",
        "oxygen",
        "exchange_reaction",
        "metabolite_name",
        "intake_flux",
    }
    missing_columns = required_columns - set(intake_df.columns)
    if missing_columns:
        print(f"Skipping top-intake plot because columns are missing: {missing_columns}")
        return None

    if oxygen_value is None:
        oxygen_value = intake_df["oxygen"].max(skipna=True)

    plot_df = intake_df[
        (intake_df["model"] == model_name)
        & (intake_df["medium_condition"] == medium_condition)
        & np.isclose(intake_df["oxygen"], oxygen_value)
    ].copy()

    if not include_oxygen:
        plot_df = plot_df[plot_df["exchange_reaction"] != "EX_o2_e"]

    plot_df = plot_df.dropna(subset=["intake_flux"])
    plot_df = plot_df[plot_df["intake_flux"] > 1e-9]

    if plot_df.empty:
        print(f"Skipping empty top-intake plot: {model_name}, {medium_condition}")
        return None

    plot_df["label"] = np.where(
        plot_df["metabolite_name"].notna(),
        plot_df["metabolite_name"].astype(str),
        plot_df["exchange_reaction"].astype(str),
    )

    plot_df = plot_df.sort_values("intake_flux", ascending=False).head(top_n)
    plot_df = plot_df.sort_values("intake_flux", ascending=True)

    plt.figure(figsize=(9, max(4.5, 0.35 * len(plot_df))))
    plt.barh(plot_df["label"], plot_df["intake_flux"])
    plt.xlabel("Intake flux")
    plt.ylabel("Medium metabolite")
    plt.title(
        f"Top medium intakes for {model_name} in {medium_condition} medium "
        f"at O2 = {oxygen_value:g}"
    )
    plt.grid(True, axis="x")

    filename = (
        f"top_{top_n}_medium_intakes_"
        f"{safe_filename(model_name)}_"
        f"{safe_filename(medium_condition)}_"
        f"o2_{safe_filename(f'{oxygen_value:g}')}.png"
    )
    save_path = output_dir / filename
    plt.savefig(save_path, dpi=150, bbox_inches="tight")
    plt.close()

    print(f"Saved top-intake bar plot: {save_path}")
    return save_path


# -----------------------------------------------------------------------------
# Main plotting workflow
# -----------------------------------------------------------------------------

def make_growth_plots(
    oxygen_df: pd.DataFrame,
    output_dir: Path,
    y_max: float | None,
) -> list[Path]:
    """Create growth plots from all_oxygen_sweep_df.csv."""

    saved_paths = []
    models = sorted(oxygen_df["model"].dropna().unique())
    medium_conditions = sorted(oxygen_df["medium_condition"].dropna().unique())
    sample_types = sorted(oxygen_df["sample_type"].dropna().unique()) if "sample_type" in oxygen_df.columns else []

    # 1. For each model, compare all media across the oxygen gradient.
    for model_name in models:
        path = save_growth_plot(
            df=oxygen_df,
            filter_column="model",
            filter_value=model_name,
            group_column="medium_condition",
            title=f"{model_name}: growth across media",
            filename=f"growth_by_medium_{safe_filename(model_name)}.png",
            output_dir=output_dir,
            y_max=y_max,
        )
        if path is not None:
            saved_paths.append(path)

    # 2. For each medium, compare all models across the oxygen gradient.
    for medium_condition in medium_conditions:
        path = save_growth_plot(
            df=oxygen_df,
            filter_column="medium_condition",
            filter_value=medium_condition,
            group_column="model",
            title=f"All models: growth in {medium_condition} medium",
            filename=f"growth_by_model_{safe_filename(medium_condition)}_medium.png",
            output_dir=output_dir,
            y_max=y_max,
        )
        if path is not None:
            saved_paths.append(path)

    # 3. For each sample type and medium, compare models within that sample type.
    if sample_types:
        for sample_type in sample_types:
            sample_df = oxygen_df[oxygen_df["sample_type"] == sample_type].copy()
            for medium_condition in medium_conditions:
                path = save_growth_plot(
                    df=sample_df,
                    filter_column="medium_condition",
                    filter_value=medium_condition,
                    group_column="model",
                    title=f"{sample_type}: growth in {medium_condition} medium",
                    filename=(
                        f"growth_{safe_filename(sample_type)}_models_"
                        f"{safe_filename(medium_condition)}_medium.png"
                    ),
                    output_dir=output_dir,
                    y_max=y_max,
                )
                if path is not None:
                    saved_paths.append(path)

    # 4. Recreate the selected comparison from the original script, but with the wider y-axis.
    selected_models = ["control", "stm1090", "mixed_stm1090"]
    selected_df = oxygen_df[oxygen_df["model"].isin(selected_models)].copy()

    if not selected_df.empty:
        for medium_condition in medium_conditions:
            path = save_growth_plot(
                df=selected_df,
                filter_column="medium_condition",
                filter_value=medium_condition,
                group_column="model",
                title=(
                    "Control, STM 10/90, and mixed STM 10/90 growth "
                    f"in {medium_condition} medium"
                ),
                filename=f"selected_models_{safe_filename(medium_condition)}_medium.png",
                output_dir=output_dir,
                y_max=y_max,
            )
            if path is not None:
                saved_paths.append(path)

    return saved_paths


def make_medium_intake_plots(
    intake_df: pd.DataFrame,
    output_dir: Path,
) -> list[Path]:
    """Create selected intake plots from all_medium_intake_df.csv."""

    saved_paths = []
    medium_conditions = sorted(intake_df["medium_condition"].dropna().unique())

    # 1. Oxygen intake across the oxygen gradient for each medium.
    for medium_condition in medium_conditions:
        path = save_intake_line_plot(
            intake_df=intake_df,
            medium_condition=medium_condition,
            exchange_reaction="EX_o2_e",
            group_column="model",
            title=f"Oxygen intake across gradient in {medium_condition} medium",
            filename=f"oxygen_intake_by_model_{safe_filename(medium_condition)}_medium.png",
            output_dir=output_dir,
        )
        if path is not None:
            saved_paths.append(path)

    # 2. Top non-oxygen medium intakes for the main comparison models at max oxygen.
    selected_models = ["control", "stm1090", "mixed_stm1090"]
    available_models = set(intake_df["model"].dropna().unique())
    selected_models = [model for model in selected_models if model in available_models]

    max_oxygen = intake_df["oxygen"].max(skipna=True)

    for model_name in selected_models:
        for medium_condition in medium_conditions:
            path = save_top_intake_bar_plot(
                intake_df=intake_df,
                model_name=model_name,
                medium_condition=medium_condition,
                output_dir=output_dir,
                oxygen_value=max_oxygen,
                top_n=15,
                include_oxygen=False,
            )
            if path is not None:
                saved_paths.append(path)

    return saved_paths


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Plot oxygen-sweep and medium-intake results from saved CSV files."
    )
    parser.add_argument(
        "--results-dir",
        type=Path,
        default=get_default_results_dir(),
        help="Directory containing all_oxygen_sweep_df.csv and optional all_medium_intake_df.csv.",
    )
    parser.add_argument(
        "--plot-dir",
        type=Path,
        default=None,
        help="Directory where plot images should be saved. Defaults to <results-dir>/plots_from_csv.",
    )
    parser.add_argument(
        "--ymax",
        type=float,
        default=20.0,
        help=(
            "Fixed y-axis maximum for objective-value plots. The script will automatically "
            "increase this if observed objective values are greater than the requested ymax. "
            "Use --auto-ymax to ignore this fixed value."
        ),
    )
    parser.add_argument(
        "--auto-ymax",
        action="store_true",
        help="Use an automatic y-axis maximum based on each plot instead of a fixed y-axis max.",
    )

    args = parser.parse_args()

    results_dir = args.results_dir.expanduser().resolve()
    plot_dir = args.plot_dir.expanduser().resolve() if args.plot_dir else results_dir / "plots_from_csv"
    plot_dir.mkdir(parents=True, exist_ok=True)

    y_max = None if args.auto_ymax else args.ymax

    print(f"Reading CSV files from: {results_dir}")
    print(f"Saving plot images to:  {plot_dir}")
    print(f"Objective-value y-axis max: {'automatic per plot' if y_max is None else y_max}")

    oxygen_csv = results_dir / "all_oxygen_sweep_df.csv"
    oxygen_df = clean_oxygen_sweep_df(read_required_csv(oxygen_csv))

    saved_growth_plots = make_growth_plots(
        oxygen_df=oxygen_df,
        output_dir=plot_dir,
        y_max=y_max,
    )

    intake_csv = results_dir / "all_medium_intake_df.csv"
    saved_intake_plots = []

    if intake_csv.exists():
        intake_df = clean_medium_intake_df(pd.read_csv(intake_csv))
        saved_intake_plots = make_medium_intake_plots(
            intake_df=intake_df,
            output_dir=plot_dir,
        )
    else:
        print(f"Optional medium-intake CSV was not found, so intake plots were skipped: {intake_csv}")

    plot_index = pd.DataFrame(
        {
            "plot_path": [str(path) for path in [*saved_growth_plots, *saved_intake_plots]],
            "plot_filename": [path.name for path in [*saved_growth_plots, *saved_intake_plots]],
        }
    )
    plot_index_path = plot_dir / "plot_index.csv"
    plot_index.to_csv(plot_index_path, index=False)

    print(f"Saved {len(saved_growth_plots)} growth plots.")
    print(f"Saved {len(saved_intake_plots)} intake plots.")
    print(f"Saved plot index: {plot_index_path}")
    print("Plotting script completed.")


if __name__ == "__main__":
    main()
